def backfill_scope_conversion_defaults(apps, schema_editor):
    """Move tenant-owned global defaults into only that tenant's datasource policies."""

    alias = schema_editor.connection.alias
    settings = apps.get_model("lens", "GlobalSetting").objects.using(alias)
    owners = apps.get_model("lens", "LLMConfigScope").objects.using(alias)
    sources = apps.get_model("lens", "DataSource").objects.using(alias)
    for field in ("vision_model_ref", "document_model_ref"):
        setting = settings.filter(key=f"lens.datasource_conversion.{field}").first()
        if setting is None or not setting.value:
            continue
        try:
            owner = owners.filter(config__uuid=UUID(str(setting.value))).first()
        except (ValueError, TypeError):
            owner = None
        if owner is not None and owner.tenant_id is None:
            continue
        if owner is not None:
            for source in sources.filter(tenant_id=owner.tenant_id).iterator():
                policy = dict(source.sync_policy or {})
                conversion = dict(policy.get("conversion") or {})
                if not conversion.get(field):
                    conversion[field] = str(setting.value)
                    policy["conversion"] = conversion
                    sources.filter(pk=source.pk).update(sync_policy=policy)
        settings.filter(pk=setting.pk).update(value="")


